<?php
namespace App\Http\Controllers;
use App\Services\DocumentIntegrationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class QualityAuditController extends Controller{
private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('quality_head')||$r->user()->canDo('quality.audit'),403);}
public function audits(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('quality_audits')->where('academic_period_id',$p->id)->orderByDesc('planned_on')->get();$users=DB::table('users')->orderBy('name')->get();return view('quality.audits',compact('rows','users'));}
public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['type'=>'required|in:internal,process,program,department','title'=>'required|string|max:500','planned_on'=>'required|date','scope'=>'nullable|string|max:1000','criteria'=>'nullable|string|max:10000','responsible_user_id'=>'nullable|exists:users,id']);DB::table('quality_audits')->insert($d+['academic_period_id'=>$p->id,'status'=>'planned','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function update(Request $r,$audit){$this->ok($r);abort_unless(DB::table('quality_audits')->where('id',$audit)->exists(),404);$d=$r->validate(['type'=>'required|in:internal,process,program,department','title'=>'required|string|max:500','planned_on'=>'required|date','scope'=>'nullable|string|max:1000','criteria'=>'nullable|string|max:10000','responsible_user_id'=>'nullable|exists:users,id']);DB::table('quality_audits')->where('id',$audit)->update($d+['updated_at'=>now()]);return back()->with('success','Проверка обновлена');}
public function destroy(Request $r,$audit){$this->ok($r);abort_unless(DB::table('quality_audits')->where('id',$audit)->exists(),404);DB::table('quality_audits')->where('id',$audit)->update(['status'=>'cancelled','updated_at'=>now()]);return back()->with('success','Проверка отменена');}
public function show(Request $r,$audit){$this->ok($r);$a=DB::table('quality_audits')->find($audit);abort_if(!$a,404);$findings=DB::table('quality_findings')->where('quality_audit_id',$audit)->get();foreach($findings as $f)$f->actions=DB::table('quality_actions as a')->leftJoin('users as u','u.id','=','a.assigned_to')->where('quality_finding_id',$f->id)->select('a.*','u.name assignee_name')->get();$users=DB::table('users')->orderBy('name')->get();return view('quality.audit-show',compact('a','findings','users'));}
public function finding(Request $r,$audit){$this->ok($r);$d=$r->validate(['severity'=>'required|in:observation,minor,major,critical','area'=>'required|string|max:255','finding'=>'required|string|max:10000','evidence'=>'nullable|string|max:10000','due_on'=>'nullable|date']);DB::table('quality_findings')->insert($d+['quality_audit_id'=>$audit,'status'=>'open','created_at'=>now(),'updated_at'=>now()]);DB::table('quality_audits')->where('id',$audit)->update(['status'=>'in_progress','updated_at'=>now()]);return back();}
public function action(Request $r,$finding){$this->ok($r);$d=$r->validate(['title'=>'required|string|max:500','action'=>'required|string|max:10000','assigned_to'=>'nullable|exists:users,id','due_on'=>'nullable|date']);DB::table('quality_actions')->insert($d+['quality_finding_id'=>$finding,'status'=>'planned','created_at'=>now(),'updated_at'=>now()]);return back();}
public function findingStatus(Request $r,$finding){$this->ok($r);$d=$r->validate(['status'=>'required|in:open,in_progress,resolved,closed']);$f=DB::table('quality_findings')->find($finding);abort_if(!$f,404);if(in_array($d['status'],['resolved','closed']))abort_if(DB::table('quality_actions')->where('quality_finding_id',$finding)->whereNotIn('status',['done','cancelled'])->exists(),422,'Сначала завершите корректирующие мероприятия.');DB::table('quality_findings')->where('id',$finding)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус несоответствия обновлён');}
public function actionUpdate(Request $r,$action){$this->ok($r);abort_unless(DB::table('quality_actions')->where('id',$action)->exists(),404);$d=$r->validate(['title'=>'required|string|max:500','action'=>'required|string|max:10000','assigned_to'=>'nullable|exists:users,id','due_on'=>'nullable|date']);DB::table('quality_actions')->where('id',$action)->update($d+['updated_at'=>now()]);return back()->with('success','Мероприятие обновлено');}
public function actionStatus(Request $r,$action){$this->ok($r);$d=$r->validate(['status'=>'required|in:planned,in_progress,done,cancelled']);abort_unless(DB::table('quality_actions')->where('id',$action)->exists(),404);DB::table('quality_actions')->where('id',$action)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус мероприятия обновлён');}
public function complete(Request $r,$audit){$this->ok($r);$a=DB::table('quality_audits')->find($audit);abort_if(!$a,404);$open=DB::table('quality_actions as qa')->join('quality_findings as qf','qf.id','=','qa.quality_finding_id')->where('qf.quality_audit_id',$audit)->whereNotIn('qa.status',['done','cancelled'])->exists();abort_if($open,422,'Нельзя завершить проверку: есть незавершённые мероприятия.');$openFindings=DB::table('quality_findings')->where('quality_audit_id',$audit)->whereNotIn('status',['resolved','closed'])->exists();abort_if($openFindings,422,'Закройте или устраните все несоответствия.');DB::table('quality_audits')->where('id',$audit)->update(['status'=>'completed','updated_at'=>now()]);return back()->with('success','Проверка завершена');}
public function edo(Request $r,$audit,DocumentIntegrationService $docs){$this->ok($r);$a=DB::table('quality_audits')->find($audit);abort_if(!$a,404);$snap=['audit'=>$a,'findings'=>DB::table('quality_findings')->where('quality_audit_id',$audit)->get()];$id=$docs->create($r->user(),$a->academic_period_id,'quality','audit',$audit,'quality_audit','Акт внутренней проверки: '.$a->title,$snap,['summary'=>$a->conclusion]);return redirect()->route('edo.show',$id);}
}